{"target": {"id": "fragment-9f2af16856f842e5bbd1", "kind": "function", "contract": "ExchangeService", "signature": "take(uint256)", "visibility": "external", "source": "function take(uint256 _id) external payable onlyExists(_id) returns(uint256) {

        address _owner = asks[_id].owner;
        uint256 _eth = asks[_id].pack;
        uint256 _sysEth = _eth.mul(commission).div(divider);
        systemETH = systemETH.add(_sysEth);
        uint256 _tmv = _eth.mul(ILogic(settings.logicManager()).rate()).div(ILogic(settings.logicManager()).precision());
        uint256 _box = ILogic(settings.logicManager()).create.value(msg.value)(_tmv);
        uint256 _sysTmv = _tmv.mul(commission).div(divider);
        delete asks[_id];
        msg.sender.transfer(_eth.sub(_sysEth));
        ILogic(settings.logicManager()).transferFrom(address(this), msg.sender, _box);
        IToken(settings.tmvAddress()).transfer(_owner, _tmv.sub(_sysTmv));
        emit AskMatched(_id, _box, msg.sender, _owner);
        return _tmv.sub(_sysTmv);
    }", "state_reads": ["asks", "commission", "divider", "settings", "systemETH"], "state_writes": ["asks", "systemETH"], "modifiers": [{"fragment_id": "fragment-63067ca066e1b37f3fd7", "name": "onlyExists", "state_reads": ["asks"], "state_writes": []}], "state_dependencies": [{"id": "ExchangeService.asks", "name": "asks", "declaration_id": "fragment-548d4e4ab103336fd3d1", "direct_writers": [{"fragment_id": "fragment-4fcf17be6d47a1258bcf", "signature": "close(uint256)", "kind": "function"}, {"fragment_id": "fragment-9f2af16856f842e5bbd1", "signature": "take(uint256)", "kind": "function"}]}, {"id": "ExchangeService.commission", "name": "commission", "declaration_id": "fragment-247122b0fa13a76001e8", "direct_writers": [{"fragment_id": "fragment-e1702005b5c2c4ddec5b", "signature": "constructor(ISettings)", "kind": "function"}, {"fragment_id": "fragment-f162a467d7f57eaa0ba4", "signature": "setCommission(uint256)", "kind": "function"}]}, {"id": "ExchangeService.divider", "name": "divider", "declaration_id": "fragment-ee0223a76a77ddfce620", "direct_writers": []}, {"id": "ExchangeService.settings", "name": "settings", "declaration_id": "fragment-4a153a194c5375e69b2b", "direct_writers": [{"fragment_id": "fragment-e1702005b5c2c4ddec5b", "signature": "constructor(ISettings)", "kind": "function"}]}, {"id": "ExchangeService.systemETH", "name": "systemETH", "declaration_id": "fragment-dcc80bc352f5656ddb7d", "direct_writers": [{"fragment_id": "fragment-703d6645523b675e43e7", "signature": "withdrawSystemETH(address)", "kind": "function"}, {"fragment_id": "fragment-9f2af16856f842e5bbd1", "signature": "take(uint256)", "kind": "function"}]}], "preparation_mode": "FULL_INDEX"}, "available_context": [{"id": "fragment-d49da902bab3abd3bd8d", "kind": "function", "name": "create(uint256)"}, {"id": "fragment-c0764869ee4a491eb4fc", "kind": "function", "name": "precision()"}, {"id": "fragment-667c7d3aee170e52b0b2", "kind": "function", "name": "rate()"}, {"id": "fragment-3a00b5d10c5264bd6c7a", 